package cn.zhuatech.privacy.deep;import cn.zhuatech.privacy.common.ApiResponse;import org.springframework.web.bind.annotation.*;import java.time.*;@RestController @RequestMapping("/api/admin/privacy-ops") public class DeepAdminController{private final DeepDomainService s;public DeepAdminController(DeepDomainService s){this.s=s;}@PostMapping("/assessments/{id}/approve")ApiResponse<?> assessment(@PathVariable Long id){return ApiResponse.ok(s.approveAssessment(id));}@PostMapping("/activities/{id}/approve")ApiResponse<?> activity(@PathVariable Long id){return ApiResponse.ok(s.approveActivity(id));}@PostMapping("/retention/run")ApiResponse<?> retention(@RequestParam String organizationCode,@RequestParam LocalDate asOf){return ApiResponse.ok(s.runRetention(organizationCode,asOf));}}
